<?php
session_start();
require __DIR__ . '/db.php';
require __DIR__ . '/helpers.php';
if (empty($_SESSION['user_id'])) { header('Location: login.php'); exit; }
get_csrf_token();
$pdo=get_pdo(); $stmt=$pdo->prepare('SELECT username,role FROM users WHERE id=?'); $stmt->execute([$_SESSION['user_id']]); $user=$stmt->fetch();
if (!$user || $user['role']!=='admin') { http_response_code(403); exit('Acesso negado'); }
header('X-Frame-Options: DENY'); header('X-Content-Type-Options: nosniff');
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Social Media — Uplar</title>
<style>
:root{--p:#3b6ff5;--ink:#0f1c2e;--muted:#64748b;--bg:#f4f6fb;--card:#fff;--border:#e2e8f0;--ok:#059669;--err:#dc2626}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 Inter,system-ui,sans-serif}.top{height:64px;background:#fff;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;padding:0 24px;position:sticky;top:0;z-index:5}.brand{font-size:20px;font-weight:800;color:var(--p)}.wrap{max-width:1280px;margin:0 auto;padding:24px}.tabs{display:flex;gap:8px;margin:20px 0}.tabs button,.btn{border:1px solid var(--border);background:#fff;border-radius:9px;padding:9px 13px;font-weight:700;cursor:pointer}.tabs .on,.btn.primary{background:var(--p);border-color:var(--p);color:white}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(285px,1fr));gap:16px}.card{background:var(--card);border:1px solid var(--border);border-radius:14px;overflow:hidden;box-shadow:0 3px 14px #0f172a0a}.media{aspect-ratio:4/5;background:#e8eefb;display:grid;place-items:center;overflow:hidden}.media img,.media video{width:100%;height:100%;object-fit:cover}.body{padding:15px}.meta{display:flex;justify-content:space-between;color:var(--muted);font-size:12px}.badge{padding:3px 8px;border-radius:99px;background:#eef2ff;color:#3346a8}.caption{width:100%;min-height:100px;margin:12px 0;padding:10px;border:1px solid var(--border);border-radius:8px;resize:vertical}.date{width:100%;padding:9px;border:1px solid var(--border);border-radius:8px}.actions{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}.btn.danger{color:var(--err)}.empty{background:white;border:1px dashed var(--border);padding:40px;text-align:center;border-radius:12px;color:var(--muted)}.interaction{background:#fff;border:1px solid var(--border);border-radius:12px;padding:15px;margin-bottom:10px}.toast{position:fixed;right:20px;bottom:20px;background:#111827;color:#fff;padding:12px 16px;border-radius:9px;display:none}@media(max-width:600px){.wrap{padding:15px}.top{padding:0 15px}}
</style></head><body><header class="top"><div><span class="brand">UPLAR</span> · Social Media</div><a href="config.php">Voltar ao painel</a></header><main class="wrap"><h1>Central de conteúdo</h1><p>Revise criativos e acompanhe conversas antes da publicação.</p><div class="tabs"><button id="tabContent" class="on">Conteúdo</button><button id="tabInteractions">Interações <span id="pendingCount"></span></button><button id="refresh">Atualizar</button></div><section id="content"><div class="empty">Carregando…</div></section><section id="interactions" hidden></section></main><div id="toast" class="toast"></div>
<script>
const CSRF=<?= json_encode(get_csrf_token()) ?>, api='social_media_api.php';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
async function call(action,data={}){const fd=new FormData();fd.append('csrf_token',CSRF);fd.append('action',action);Object.entries(data).forEach(([k,v])=>fd.append(k,v??''));const r=await fetch(api,{method:'POST',body:fd,credentials:'same-origin'});const j=await r.json().catch(()=>({error:'Resposta inválida'}));if(!r.ok||!j.ok)throw new Error(j.error||'Falha');return j}
function toast(msg){const e=document.querySelector('#toast');e.textContent=msg;e.style.display='block';setTimeout(()=>e.style.display='none',3000)}
function localDate(v){if(!v)return'';const d=new Date(v),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`}
async function loadContent(){const root=document.querySelector('#content');root.innerHTML='<div class="empty">Carregando…</div>';try{const {items}=await call('list_content');root.className='grid';root.innerHTML=items.length?items.map(i=>`<article class="card" data-id="${i.id}"><div class="media">${i.media_url?(i.media_type==='video/mp4'?`<video controls preload="metadata" src="${esc(i.media_url)}"></video>`:`<img loading="lazy" src="${esc(i.media_url)}" alt="Prévia">`):'Criativo em geração'}</div><div class="body"><div class="meta"><span>${esc(i.content_type)}</span><span class="badge">${esc(i.status)}</span></div><h3>${esc(i.title)}</h3><textarea class="caption">${esc(i.caption)}</textarea><input class="date" type="datetime-local" value="${localDate(i.scheduled_at)}"><div class="actions"><button class="btn save">Salvar</button><button class="btn primary approve" ${!i.media_url?'disabled':''}>Aprovar</button><button class="btn regen">Regenerar</button><button class="btn danger reject">Rejeitar</button></div>${i.error_message?`<p style="color:var(--err)">${esc(i.error_message)}</p>`:''}</div></article>`).join(''):'<div class="empty">Nenhum conteúdo encontrado.</div>'}catch(e){root.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function loadInteractions(){const root=document.querySelector('#interactions');try{const {items}=await call('list_interactions');const pending=items.filter(i=>!i.handled_at);document.querySelector('#pendingCount').textContent=pending.length?`(${pending.length})`:'';root.innerHTML=items.length?items.map(i=>`<article class="interaction" data-id="${i.id}"><div class="meta"><strong>${esc(i.username||'Usuário do Instagram')}</strong><span>${new Date(i.received_at).toLocaleString('pt-BR')}</span></div><p>${esc(i.notes||'Interação recebida')}</p><span class="badge">${esc(i.interest||'não classificado')}</span>${i.handled_at?' <span>Atendida</span>':` <button class="btn handled">Marcar como atendida</button>`}</article>`).join(''):'<div class="empty">Nenhuma interação recebida.</div>'}catch(e){root.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
document.addEventListener('click',async e=>{const card=e.target.closest('[data-id]');if(!card)return;const id=card.dataset.id;try{if(e.target.matches('.save,.approve')){const data={id,caption:card.querySelector('.caption').value,scheduled_at:card.querySelector('.date').value};await call('update_content',data);if(e.target.matches('.approve'))await call('approve',data)}else if(e.target.matches('.reject'))await call('reject',{id}) ;else if(e.target.matches('.regen'))await call('regenerate',{id});else if(e.target.matches('.handled'))await call('mark_handled',{id});else return;toast('Atualizado com sucesso');await Promise.all([loadContent(),loadInteractions()])}catch(err){toast(err.message)}});
document.querySelector('#tabContent').onclick=()=>{content.hidden=false;interactions.hidden=true;tabContent.className='on';tabInteractions.className=''};document.querySelector('#tabInteractions').onclick=()=>{content.hidden=true;interactions.hidden=false;tabContent.className='';tabInteractions.className='on'};document.querySelector('#refresh').onclick=()=>Promise.all([loadContent(),loadInteractions()]);loadContent();loadInteractions();
</script></body></html>
